```go
// TrailsFilter narrows a cross-repo trail read. Zero values disable each filter.
type TrailsFilter struct {
	Statuses        []string // empty = all statuses
	AuthorAccountID string   // "" = any author; else repo_trails.author_account_id = this ULID
	Limit           int      // rows returned (total is reported unclamped)
}

// AccountTrailRow is a TrailListRow plus the repo-identity columns the
// account-scoped list needs to label each row (rows span many repos).
type AccountTrailRow struct {
	TrailListRow
	RepoFullName string
	IsPrivate    bool
}

// TrailsForRepos lists trails across a set of repos (repo_id = ANY), updated_at
// DESC (id DESC tiebreak), capped at f.Limit. It returns the capped rows plus
// the full match count (total) so a truncated page never reads as the total.
// full_name/private come from repos + github_repo_meta (same JOIN shape as
// openPullRequestsChunk); private is NULL pre-observation, coalesced to false.
func (s *RepoStore) TrailsForRepos(ctx context.Context, repoIDs []string, f TrailsFilter) ([]AccountTrailRow, int, error) {
	if len(repoIDs) == 0 {
		return nil, 0, nil
	}
	idB, err := ulidBytesList(repoIDs)
	if err != nil {
		return nil, 0, fmt.Errorf("store: trails for repos: %w", err)
	}
	conds := []string{"t.repo_id = ANY($1)"}
	args := []any{idB}
	if len(f.Statuses) > 0 {
		args = append(args, f.Statuses)
		conds = append(conds, fmt.Sprintf("t.status = ANY($%d)", len(args)))
	}
	if f.AuthorAccountID != "" {
		aid, err := ulidBytes(f.AuthorAccountID)
		if err != nil {
			return nil, 0, fmt.Errorf("store: trails for repos: author: %w", err)
		}
		args = append(args, aid)
		conds = append(conds, fmt.Sprintf("t.author_account_id = $%d", len(args)))
	}
	where := strings.Join(conds, " AND ")

	var total int
	if err := s.pool.QueryRow(ctx,
		`SELECT count(*) FROM repo_trails t WHERE `+where, args...).Scan(&total); err != nil {
		return nil, 0, fmt.Errorf("store: trails for repos: count: %w", err)
	}

	limit := f.Limit
	if limit <= 0 || limit > 1000 {
		limit = 100
	}
	args = append(args, limit)
	q := `
		SELECT t.id, t.number, t.title, t.status,
			COALESCE(t.branch, ''), COALESCE(t.original_branch, ''),
			t.base, t.type, COALESCE(t.priority, ''),
			t.author_account_id,
			t.assignees, t.reviewers, t.requested_reviewers,
			t.has_code_changes, t.comment_count, t.unresolved_count,
			t.created_at, t.updated_at, t.merged_at,
			COALESCE(g.full_name, r.full_name, ''), COALESCE(g.private, false)
		FROM repo_trails t
		JOIN repos r ON r.id = t.repo_id
		LEFT JOIN github_repo_meta g ON g.repo_id = t.repo_id
		WHERE ` + where + `
		ORDER BY t.updated_at DESC, t.id DESC
		LIMIT $` + strconv.Itoa(len(args))
	rows, err := s.pool.Query(ctx, q, args...)
	if err != nil {
		return nil, 0, fmt.Errorf("store: trails for repos: select: %w", err)
	}
	out, err := pgx.CollectRows(rows, func(r pgx.CollectableRow) (AccountTrailRow, error) {
		var (
			tr         AccountTrailRow
			id, author []byte
		)
		if err := r.Scan(&id, &tr.Number, &tr.Title, &tr.Status,
			&tr.Branch, &tr.OriginalBranch, &tr.Base, &tr.Type, &tr.Priority,
			&author, &tr.Assignees, &tr.Reviewers, &tr.RequestedReviewers,
			&tr.HasCodeChanges, &tr.CommentCount, &tr.UnresolvedCount,
			&tr.CreatedAt, &tr.UpdatedAt, &tr.MergedAt,
			&tr.RepoFullName, &tr.IsPrivate); err != nil {
			return tr, fmt.Errorf("scan account trail: %w", err)
		}
		tr.ID = ulidText(id)
		tr.AuthorAccountID = ulidText(author)
		return tr, nil
	})
	if err != nil {
		return nil, 0, fmt.Errorf("store: trails for repos: scan: %w", err)
	}
	return out, total, nil
}
```

