package httpapi

import (
	"context"
	"net/http"
	"strings"

	"github.com/danielgtaylor/huma/v2"

	"github.com/entirehq/entire-api/internal/store"
)

// meTrailAuthor mirrors the CLI's trail.Author (snake_case wire shape).
type meTrailAuthor struct {
	ID    string `json:"id"`
	Login string `json:"login,omitempty"`
}

// meTrailItem is one account-scoped trail. Field JSON tags match the CLI's
// api.TrailResource so the CLI decodes /me/trails with its existing type plus
// repo_full_name + is_private. Login enrichment is a follow-up (v1: id only).
type meTrailItem struct {
	ID              string         `json:"id"`
	Number          int            `json:"number"`
	Title           string         `json:"title"`
	Status          string         `json:"status"`
	Branch          string         `json:"branch"`
	Base            string         `json:"base"`
	Author          *meTrailAuthor `json:"author"`
	CommentCount    int            `json:"comment_count,omitempty"`
	UnresolvedCount int            `json:"unresolved_count,omitempty"`
	CreatedAt       string         `json:"created_at"`
	UpdatedAt       string         `json:"updated_at"`
	RepoFullName    string         `json:"repo_full_name"`
	IsPrivate       bool           `json:"is_private"`
}

// MeTrailsInput is the query for GET /me/trails.
type MeTrailsInput struct {
	Status string   `query:"status" doc:"Comma-separated statuses; omit for all"`
	Author string   `query:"author" doc:"'me' filters to the caller's own trails"`
	Repo   []string `query:"repo,explode" doc:"forge/owner/repo to narrow to; repeatable"`
	Limit  int      `query:"limit" minimum:"1" maximum:"1000" default:"200"`
}

// MeTrailsOutput is the account-scoped list envelope.
type MeTrailsOutput struct {
	Body struct {
		Trails []meTrailItem `json:"trails"`
		Total  int           `json:"total"`
	}
}

// registerMeTrails wires GET /me/trails: the caller's trails across every repo
// they are a member of. Like /cache/prs it is an enumeration (no {repo_id} to
// gate on), so it carries only requireAuth and does its own fail-closed access
// enumeration via the SpiceDB membership set (repo/list), NOT the pull set — a
// pull scope would flood it with every public repo's trails.
func registerMeTrails(api huma.API, deps *RepoActivityDeps) {
	gate := []opMiddleware{requireAuth(api, &deps.baseDeps)}
	huma.Register(api, teamOp("meTrails", http.MethodGet, "/me/trails",
		"Your trails across your repositories", "me", gate),
		func(ctx context.Context, in *MeTrailsInput) (*MeTrailsOutput, error) {
			set, err := memberRepoSet(ctx, deps.Reader)
			if err != nil {
				return nil, err
			}
			ids, err := scopeAccountRepoIDs(ctx, deps, set, in.Repo)
			if err != nil {
				return nil, err
			}
			f := store.TrailsFilter{Statuses: splitCSV(in.Status), Limit: in.Limit}
			if in.Author == "me" {
				f.AuthorAccountID = id(ctx)
			}
			rows, total, err := deps.Store.TrailsForRepos(ctx, ids, f)
			if err != nil {
				return nil, huma.Error500InternalServerError("store: trails for repos", err)
			}
			out := &MeTrailsOutput{}
			out.Body.Trails = meTrailItems(rows)
			out.Body.Total = total
			return out, nil
		})
}

// scopeAccountRepoIDs turns the member set into a []string of repo ids, and —
// when a repo filter is present — intersects it with the resolved filter ids so
// the filter can only narrow, never widen, access.
func scopeAccountRepoIDs(ctx context.Context, deps *RepoActivityDeps, set map[string]struct{}, repoFilter []string) ([]string, error) {
	if len(repoFilter) == 0 {
		ids := make([]string, 0, len(set))
		for repoID := range set {
			ids = append(ids, repoID)
		}
		return ids, nil
	}
	var ids []string
	for _, spec := range repoFilter {
		fullName, ok := fullNameFromRepoSpec(spec)
		if !ok {
			continue
		}
		repoID, found, err := deps.Store.RepoIDByFullName(ctx, fullName)
		if err != nil {
			return nil, huma.Error500InternalServerError("store: repo id by full name", err)
		}
		if !found {
			continue
		}
		if _, member := set[repoID]; member {
			ids = append(ids, repoID)
		}
	}
	return ids, nil
}

// fullNameFromRepoSpec parses "forge/owner/repo" (e.g. gh/acme/app) into the
// "owner/repo" full_name RepoIDByFullName expects. A bare "owner/repo" is also
// accepted. Anything else is skipped by the caller.
func fullNameFromRepoSpec(spec string) (string, bool) {
	spec = strings.TrimSpace(spec)
	parts := strings.Split(strings.Trim(spec, "/"), "/")
	switch len(parts) {
	case 3:
		return parts[1] + "/" + parts[2], parts[1] != "" && parts[2] != ""
	case 2:
		return parts[0] + "/" + parts[1], parts[0] != "" && parts[1] != ""
	default:
		return "", false
	}
}

func splitCSV(s string) []string {
	s = strings.TrimSpace(s)
	if s == "" {
		return nil
	}
	var out []string
	for _, p := range strings.Split(s, ",") {
		if p = strings.TrimSpace(p); p != "" {
			out = append(out, p)
		}
	}
	return out
}

func meTrailItems(rows []store.AccountTrailRow) []meTrailItem {
	out := make([]meTrailItem, 0, len(rows))
	for _, r := range rows {
		var author *meTrailAuthor
		if r.AuthorAccountID != "" {
			author = &meTrailAuthor{ID: r.AuthorAccountID}
		}
		out = append(out, meTrailItem{
			ID:              r.ID,
			Number:          r.Number,
			Title:           r.Title,
			Status:          r.Status,
			Branch:          r.Branch,
			Base:            r.Base,
			Author:          author,
			CommentCount:    r.CommentCount,
			UnresolvedCount: r.UnresolvedCount,
			CreatedAt:       isoTime(r.CreatedAt),
			UpdatedAt:       isoTime(r.UpdatedAt),
			RepoFullName:    r.RepoFullName,
			IsPrivate:       r.IsPrivate,
		})
	}
	return out
}

