package httpapi

import (
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/entirehq/entire-api/internal/store"
)

// meTrailsBody is the decoded GET /api/v1/me/trails envelope (only the fields
// this test asserts on).
type meTrailsBody struct {
	Trails []struct {
		ID           string `json:"id"`
		Number       int    `json:"number"`
		Status       string `json:"status"`
		RepoFullName string `json:"repo_full_name"`
		IsPrivate    bool   `json:"is_private"`
	} `json:"trails"`
	Total int `json:"total"`
}

func getMeTrails(t *testing.T, r *Router, bearer, query string) meTrailsBody {
	t.Helper()
	req := httptest.NewRequest(http.MethodGet, "/api/v1/me/trails"+query, nil)
	req.Header.Set("Authorization", "Bearer "+bearer)
	w := httptest.NewRecorder()
	r.HTTPHandler().ServeHTTP(w, req)
	if w.Code != http.StatusOK {
		t.Fatalf("status = %d, body = %s", w.Code, w.Body.String())
	}
	var body meTrailsBody
	if err := json.Unmarshal(w.Body.Bytes(), &body); err != nil {
		t.Fatalf("decode: %v (body %s)", err, w.Body.String())
	}
	return body
}

func TestIntegrationMeTrails(t *testing.T) {
	repoStore, userStore := openPipelineStores(t) // skips without the DB env
	ctx := context.Background()
	member := routeULID("me-trails-member-" + uniqueSuffix())
	foreign := routeULID("me-trails-foreign-" + uniqueSuffix())
	memberFull := trailsFullName(member)
	foreignFull := trailsFullName(foreign)

	if err := repoStore.UpsertRepo(ctx, store.Repo{ID: member, Jurisdiction: "us", FullName: memberFull}); err != nil {
		t.Fatalf("seed member repo: %v", err)
	}
	if err := repoStore.UpsertRepo(ctx, store.Repo{ID: foreign, Jurisdiction: "us", FullName: foreignFull}); err != nil {
		t.Fatalf("seed foreign repo: %v", err)
	}
	seedTrailsRepo(t, repoStore, member, memberFull)   // 2 trails on a repo the caller belongs to
	seedTrailsRepo(t, repoStore, foreign, foreignFull) // 2 trails on a repo the caller does NOT belong to

	// pullable == member set here (pipelineRouter's fakeReader populates both the
	// pull and repo/list sets from this slice); the caller is a member of `member`
	// only, so the foreign repo's trails must never surface.
	r, mint := pipelineRouter(t, repoStore, userStore, []string{member})

	body := getMeTrails(t, r, mint("caller"), "")
	if body.Total != 2 || len(body.Trails) != 2 {
		t.Fatalf("got %d trails total=%d, want 2/2 (foreign repo must be excluded)", len(body.Trails), body.Total)
	}
	for _, tr := range body.Trails {
		if tr.RepoFullName != memberFull {
			t.Errorf("repo_full_name = %q, want %q", tr.RepoFullName, memberFull)
		}
	}

	// A repo filter naming a non-member repo yields nothing — the filter can only
	// narrow the member set, never widen it.
	empty := getMeTrails(t, r, mint("caller"), "?repo=gh/"+foreignFull)
	if empty.Total != 0 || len(empty.Trails) != 0 {
		t.Errorf("repo filter to foreign repo got %d/%d, want 0/0", len(empty.Trails), empty.Total)
	}

	// A status filter narrows within the member set (seedTrailsRepo makes one
	// open + one merged trail).
	openOnly := getMeTrails(t, r, mint("caller"), "?status=open")
	if openOnly.Total != 1 || len(openOnly.Trails) != 1 || openOnly.Trails[0].Status != "open" {
		t.Errorf("status=open got %d/%d, want 1/1 open", len(openOnly.Trails), openOnly.Total)
	}
}

